static void case_tel_dropped_fill(void *p, uint32_t seed, const uint8_t *pool) {
    ta_msg_tel_dropped *d = p;
    ta_mem_zero(d, sizeof *d);
    d->head.flags = (uint16_t)(ring_proto_mix(seed, 0) & 0x0300u);
    d->head.session = ring_proto_mix(seed, 1);
    d->head.at = ring_proto_mix(seed, 2);
    d->count = (uint64_t)ring_proto_mix(seed, 3);
    d->first_seq = (uint64_t)ring_proto_mix(seed, 4);
    (void)pool;
}
